item.command:
/bin/bash -lc "python - <<'PY'
import urllib.request, json
for repo in ['scanpy','scipy','anndata','pandas']:
    print('REPO', repo)
    url=f'https://quay.io/api/v1/repository/biocontainers/{repo}/tag/?limit=20&onlyActiveTags=true'
    try:
        with urllib.request.urlopen(url, timeout=20) as r:
            data=json.load(r)
        for t in data.get('tags',[])[:10]:
            print(t.get('name'))
    except Exception as e:
        print('ERR', e)
PY"

