# quick total/path raw ranks
import tarfile,gzip,io,csv,statistics,math
from collections import defaultdict
p='inputs/perturb.seq.effect.q1.tar.gz'
with tarfile.open(p,'r:*') as tf:
 def t(n):
  b=tf.extractfile(n).read();
  if n.endswith('.gz'): b=gzip.decompress(b)
  return io.StringIO(b.decode())
 refs=list(csv.DictReader(t('feature_reference.csv'))); calls=list(csv.DictReader(t('protospacer_calls_per_cell.csv'))); bar=[l.strip() for l in t('filtered_feature_bc_matrix/barcodes.tsv.gz')]
 m=t('filtered_feature_bc_matrix/matrix.mtx.gz'); m.readline(); line=m.readline().strip()
 while line.startswith('%'): line=m.readline().strip()
 nrow,ncol,nnz=map(int,line.split()); total=[0]*ncol; path=[0]*ncol
 for line in m:
  if line.strip():
   i,j,v=map(int,line.split()); total[j-1]+=v
   if i<=20: path[j-1]+=v
print(min(total),max(total),statistics.mean(total),statistics.stdev(total),min(path),max(path),statistics.mean(path))
gt={r['id']:r['target_gene_name'] for r in refs}; gids=[r['feature_call'] for r in calls]
ctrl=[i for i,g in enumerate(gids) if gt[g]=='Non-Targeting']
cm=statistics.mean([path[i] for i in ctrl]); print('ctrl raw',cm)
out=[]
for g,targ in gt.items():
 cs=[i for i,x in enumerate(gids) if x==g]
 if cs:
  vals=[path[i] for i in cs]
  out.append((statistics.mean(vals)-cm,targ,g,len(cs),statistics.mean(vals)))
print(sorted(out)[:10])
PY"

